SELECT t.ticker, CAST(t.time AS STRING) d, t.Open, t.Close, t.Price FROM tav2_bq.ticker AS t WHERE t.time BETWEEN "2026-07-01" AND "2026-11-16" AND t.ticker IN ("ACB","BID","CSV","CTG","DCM","DRI","EVF","FPT","HAH","HDB","HPG","HT1","LPB","MBB","MBS","MCH","MSB","MSH","NCT","NNC","PVT","SAB","SCL","SHB","SHS","SIP","TCB","TCM","TLG","TPB","TV1","VCB","VGC","VGS","VHC","VHM","VIB","VIX","VND","VNM","VPB","VPI","VRE")